class TokenBucket {
  constructor({ capacity, refillPerSecond, now }) {
    if (typeof capacity !== "number" || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError("capacity pozitif sonlu sayı olmalıdır");
    }
    if (typeof refillPerSecond !== "number" || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError("refillPerSecond negatif olmayan bir sayı olmalıdır");
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = typeof now === "function" ? now : Date.now;

    this.tokens = capacity;
    this.lastRefill = this.now();
  }

  _refill(now) {
    if (now < this.lastRefill) {
      return;
    }

    const elapsed = (now - this.lastRefill) / 1000;
    const added = elapsed * this.refillPerSecond;
    this.tokens = Math.min(this.capacity, this.tokens + added);
    this.lastRefill = now;
  }

  tryTake(n = 1) {
    if (typeof n !== "number" || !Number.isFinite(n) || n <= 0) {
      throw new RangeError("n pozitif sonlu sayı olmalıdır");
    }

    const now = this.now();
    this._refill(now);

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    const now = this.now();
    this._refill(now);
    return this.tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== "number" || !Number.isFinite(n) || n <= 0) {
      throw new RangeError("n pozitif sonlu sayı olmalıdır");
    }

    const now = this.now();
    this._refill(now);

    if (this.tokens >= n) {
      return 0;
    }

    if (this.refillPerSecond <= 0 || n > this.capacity) {
      return Infinity;
    }

    const missing = n - this.tokens;
    const ms = (missing / this.refillPerSecond) * 1000;
    return Math.ceil(ms);
  }
}

module.exports = { TokenBucket };

const { TokenBucket } = require('./kova.js');
let t = 0;
const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => t });
console.log('avail', b.available());
console.log('take10', b.tryTake(10));
console.log('take1', b.tryTake(1));
t += 500;
console.log('avail500ms', b.available());
console.log('msUntil1', b.msUntil(1));
t += 1000;
console.log('msUntil1after1s', b.msUntil(1));
console.log('backwards', (() => { t -= 1000; return b.available(); })());
try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); } catch (e) { console.log('err cap', e.name); }
try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); } catch (e) { console.log('err refill', e.name); }
try { b.tryTake(0); } catch (e) { console.log('err take0', e.name); }
console.log('inf n>cap', b.msUntil(11));
console.log('inf no refill', (() => { const b2 = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 0 }); b2.tryTake(5); return b2.msUntil(1); })());
